import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import Inventory from './views/Inventory';
import Sales from './views/Sales';
import Expenses from './views/Expenses';
import AIInsights from './views/AIInsights';
import Customers from './views/Customers';
import { Product, Sale, Expense, ProductCategory } from './types';

const INITIAL_PRODUCTS: Product[] = [
  { id: '1', name: 'Costilla de Res', category: ProductCategory.MEAT, costPrice: 15000, salePrice: 25000, stock: 10, unit: 'kg' },
  { id: '2', name: 'Punta de Anca', category: ProductCategory.MEAT, costPrice: 18000, salePrice: 32000, stock: 5, unit: 'kg' },
  { id: '3', name: 'Papas a la Francesa', category: ProductCategory.SIDES, costPrice: 2000, salePrice: 6000, stock: 50, unit: 'porcion' },
  { id: '4', name: 'Cerveza Club Colombia', category: ProductCategory.DRINKS, costPrice: 3000, salePrice: 6000, stock: 24, unit: 'unidad' },
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // State initialization from local storage or defaults
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('asadopro_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('asadopro_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('asadopro_expenses');
    return saved ? JSON.parse(saved) : [];
  });

  // Persistence
  useEffect(() => {
    localStorage.setItem('asadopro_products', JSON.stringify(products));
    localStorage.setItem('asadopro_sales', JSON.stringify(sales));
    localStorage.setItem('asadopro_expenses', JSON.stringify(expenses));
  }, [products, sales, expenses]);

  // Derived Stats
  const stats = useMemo(() => {
    const totalSales = sales.reduce((acc, s) => acc + s.total, 0);
    const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
    return {
      totalSales,
      totalExpenses,
      netProfit: totalSales - totalExpenses,
      salesCount: sales.length,
      inventoryValue: products.reduce((acc, p) => acc + (p.stock * p.costPrice), 0)
    };
  }, [sales, expenses, products]);

  const handleAddSale = (sale: Omit<Sale, 'id'>) => {
    const newSale = { ...sale, id: Math.random().toString(36).substr(2, 9) };
    setSales(prev => [newSale, ...prev]);

    // Update inventory
    setProducts(prev => prev.map(p => {
      const soldItem = sale.items.find(item => item.productId === p.id);
      if (soldItem) {
        return { ...p, stock: p.stock - soldItem.quantity };
      }
      return p;
    }));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard stats={stats} recentSales={sales.slice(0, 5)} />;
      case 'inventory':
        return <Inventory products={products} setProducts={setProducts} />;
      case 'sales':
        return <Sales sales={sales} products={products} onAddSale={handleAddSale} />;
      case 'expenses':
        return <Expenses expenses={expenses} setExpenses={setExpenses} />;
      case 'customers':
        return <Customers sales={sales} />;
      case 'ai':
        return <AIInsights stats={stats} products={products} />;
      default:
        return <Dashboard stats={stats} recentSales={sales.slice(0, 5)} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React from 'react';
import { 
  TrendingUp, 
  TrendingDown, 
  DollarSign, 
  Package, 
  ShoppingBag,
  ArrowRight
} from 'lucide-react';
import { 
  BarChart, 
  Bar, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer,
  Cell
} from 'recharts';
import { Sale } from '../types';

interface DashboardProps {
  stats: {
    totalSales: number;
    totalExpenses: number;
    netProfit: number;
    salesCount: number;
    inventoryValue: number;
  };
  recentSales: Sale[];
}

const formatCurrency = (val: number) => 
  new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }).format(val);

const Dashboard: React.FC<DashboardProps> = ({ stats, recentSales }) => {
  const chartData = [
    { name: 'Ventas', value: stats.totalSales, color: '#10b981' },
    { name: 'Gastos', value: stats.totalExpenses, color: '#ef4444' },
    { name: 'Utilidad', value: stats.netProfit, color: '#f97316' },
  ];

  return (
    <div className="space-y-6">
      {/* Stats Grid */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          title="Ventas Totales" 
          value={formatCurrency(stats.totalSales)} 
          icon={<DollarSign className="w-6 h-6 text-green-600" />} 
          trend="+12%" 
          bg="bg-green-50"
        />
        <StatCard 
          title="Utilidad Neta" 
          value={formatCurrency(stats.netProfit)} 
          icon={<TrendingUp className="w-6 h-6 text-orange-600" />} 
          trend="+5.4%" 
          bg="bg-orange-50"
        />
        <StatCard 
          title="Gastos" 
          value={formatCurrency(stats.totalExpenses)} 
          icon={<TrendingDown className="w-6 h-6 text-red-600" />} 
          trend="+2.1%" 
          bg="bg-red-50"
        />
        <StatCard 
          title="Valor Inventario" 
          value={formatCurrency(stats.inventoryValue)} 
          icon={<Package className="w-6 h-6 text-blue-600" />} 
          bg="bg-blue-50"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Chart */}
        <div className="lg:col-span-2 bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
          <h3 className="text-lg font-semibold mb-6">Comparativa Financiera</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" />
                <YAxis hide />
                <Tooltip 
                  formatter={(value: number) => formatCurrency(value)}
                  contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                  {chartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Recent Sales */}
        <div className="bg-white p-6 rounded-xl border border-gray-200 shadow-sm">
          <div className="flex justify-between items-center mb-6">
            <h3 className="text-lg font-semibold">Ventas Recientes</h3>
            <button className="text-orange-600 text-sm font-medium flex items-center gap-1 hover:underline">
              Ver todas <ArrowRight className="w-4 h-4" />
            </button>
          </div>
          <div className="space-y-4">
            {recentSales.length > 0 ? recentSales.map((sale) => (
              <div key={sale.id} className="flex items-center justify-between p-3 rounded-lg hover:bg-gray-50 transition-colors border border-transparent hover:border-gray-100">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-gray-100 rounded-lg">
                    <ShoppingBag className="w-5 h-5 text-gray-600" />
                  </div>
                  <div>
                    <p className="font-medium text-gray-900">{sale.customerName || 'Consumidor Final'}</p>
                    <p className="text-xs text-gray-500">{new Date(sale.date).toLocaleDateString()}</p>
                  </div>
                </div>
                <p className="font-bold text-gray-900">{formatCurrency(sale.total)}</p>
              </div>
            )) : (
              <p className="text-center text-gray-400 py-10">No hay ventas registradas aún.</p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

interface StatCardProps {
  title: string;
  value: string;
  icon: React.ReactNode;
  trend?: string;
  bg: string;
}

const StatCard: React.FC<StatCardProps> = ({ title, value, icon, trend, bg }) => (
  <div className={`p-6 rounded-xl border border-gray-200 shadow-sm bg-white`}>
    <div className="flex items-center justify-between mb-4">
      <div className={`p-3 rounded-lg ${bg}`}>
        {icon}
      </div>
      {trend && (
        <span className="text-xs font-semibold text-green-600 bg-green-100 px-2 py-1 rounded-full">
          {trend}
        </span>
      )}
    </div>
    <div>
      <p className="text-sm font-medium text-gray-500">{title}</p>
      <p className="text-2xl font-bold text-gray-900 mt-1">{value}</p>
    </div>
  </div>
);

export default Dashboard;

import React, { useState } from 'react';
import { Plus, Search, Filter, Edit2, Trash2, AlertCircle } from 'lucide-react';
import { Product, ProductCategory } from '../types';

interface InventoryProps {
  products: Product[];
  setProducts: React.Dispatch<React.SetStateAction<Product[]>>;
}

const Inventory: React.FC<InventoryProps> = ({ products, setProducts }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdding, setIsAdding] = useState(false);
  const [newProduct, setNewProduct] = useState<Omit<Product, 'id'>>({
    name: '',
    category: ProductCategory.MEAT,
    costPrice: 0,
    salePrice: 0,
    stock: 0,
    unit: 'kg'
  });

  const filteredProducts = products.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAddProduct = (e: React.FormEvent) => {
    e.preventDefault();
    const id = Math.random().toString(36).substr(2, 9);
    setProducts([...products, { ...newProduct, id }]);
    setIsAdding(false);
    setNewProduct({
      name: '',
      category: ProductCategory.MEAT,
      costPrice: 0,
      salePrice: 0,
      stock: 0,
      unit: 'kg'
    });
  };

  const handleDelete = (id: string) => {
    if (confirm('¿Estás seguro de eliminar este producto?')) {
      setProducts(products.filter(p => p.id !== id));
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar producto..." 
            className="w-full pl-10 pr-4 py-2 bg-white border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-orange-500"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="flex items-center justify-center gap-2 bg-orange-600 text-white px-6 py-2 rounded-lg hover:bg-orange-700 transition-colors font-medium shadow-sm"
        >
          <Plus className="w-5 h-5" />
          Agregar Producto
        </button>
      </div>

      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50 border-b border-gray-200">
              <tr>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">Nombre</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">Categoría</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">Stock</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">Precio Venta</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filteredProducts.map((product) => (
                <tr key={product.id} className="hover:bg-gray-50 transition-colors">
                  <td className="px-6 py-4">
                    <p className="font-medium text-gray-900">{product.name}</p>
                    <p className="text-xs text-gray-500">Unidad: {product.unit}</p>
                  </td>
                  <td className="px-6 py-4">
                    <span className="inline-block px-2 py-1 text-xs font-semibold bg-gray-100 text-gray-600 rounded-md">
                      {product.category}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <span className={`font-semibold ${product.stock <= 5 ? 'text-red-500' : 'text-gray-900'}`}>
                        {product.stock}
                      </span>
                      {product.stock <= 5 && <AlertCircle className="w-4 h-4 text-red-500" />}
                    </div>
                  </td>
                  <td className="px-6 py-4 font-bold text-gray-900">
                    ${product.salePrice.toLocaleString()}
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-2">
                      <button className="p-2 text-gray-400 hover:text-orange-600 rounded-lg hover:bg-orange-50">
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => handleDelete(product.id)}
                        className="p-2 text-gray-400 hover:text-red-600 rounded-lg hover:bg-red-50"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal Agregar Producto */}
      {isAdding && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50">
          <div className="bg-white rounded-2xl w-full max-w-md p-6 shadow-2xl">
            <h3 className="text-xl font-bold mb-6">Nuevo Producto</h3>
            <form onSubmit={handleAddProduct} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Nombre</label>
                <input 
                  required
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-orange-500 focus:border-transparent"
                  value={newProduct.name}
                  onChange={e => setNewProduct({...newProduct, name: e.target.value})}
                />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Categoría</label>
                  <select 
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                    value={newProduct.category}
                    onChange={e => setNewProduct({...newProduct, category: e.target.value as ProductCategory})}
                  >
                    {Object.values(ProductCategory).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Unidad</label>
                  <select 
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                    value={newProduct.unit}
                    onChange={e => setNewProduct({...newProduct, unit: e.target.value as any})}
                  >
                    <option value="kg">kg</option>
                    <option value="unidad">unidad</option>
                    <option value="porcion">porción</option>
                  </select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Costo ($)</label>
                  <input 
                    type="number"
                    required
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                    value={newProduct.costPrice}
                    onChange={e => setNewProduct({...newProduct, costPrice: Number(e.target.value)})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Precio Venta ($)</label>
                  <input 
                    type="number"
                    required
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                    value={newProduct.salePrice}
                    onChange={e => setNewProduct({...newProduct, salePrice: Number(e.target.value)})}
                  />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">Stock Inicial</label>
                <input 
                  type="number"
                  required
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg"
                  value={newProduct.stock}
