import React, { useState } from 'react';
import { Plus, ShoppingCart, X, CreditCard, Banknote, Landmark } from 'lucide-react';
import { Product, Sale } from '../types';

interface SalesProps {
  sales: Sale[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
}

const Sales: React.FC<SalesProps> = ({ sales, products, onAddSale }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [currentSaleItems, setCurrentSaleItems] = useState<{productId: string, quantity: number}[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'Efectivo' | 'Transferencia' | 'Tarjeta'>('Efectivo');

  const total = currentSaleItems.reduce((acc, item) => {
    const p = products.find(prod => prod.id === item.productId);
    return acc + (p ? p.salePrice * item.quantity : 0);
  }, 0);

  const handleAddItem = (productId: string) => {
    setCurrentSaleItems(prev => {
      const existing = prev.find(i => i.productId === productId);
      if (existing) {
        return prev.map(i => i.productId === productId ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { productId, quantity: 1 }];
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentSaleItems.length === 0) return;

    onAddSale({
      date: new Date().toISOString(),
      items: currentSaleItems.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        price: products.find(p => p.id === item.productId)?.salePrice || 0
      })),
      total,
      customerName,
      paymentMethod
    });

    setIsAdding(false);
    setCurrentSaleItems([]);
    setCustomerName('');
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h3 className="text-xl font-bold text-gray-800">Historial de Ventas</h3>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-orange-600 text-white px-6 py-2 rounded-lg hover:bg-orange-700 flex items-center gap-2 shadow-sm font-medium"
        >
          <ShoppingCart className="w-5 h-5" />
          Nueva Venta
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {sales.map(sale => (
          <div key={sale.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm">
            <div className="flex justify-between items-start mb-4">
              <div>
                <p className="text-sm text-gray-500">{new Date(sale.date).toLocaleString()}</p>
                <p className="font-bold text-gray-900">{sale.customerName || 'Consumidor Final'}</p>
              </div>
              <span className={`text-xs px-2 py-1 rounded-full font-medium ${
                sale.paymentMethod === 'Efectivo' ? 'bg-green-100 text-green-700' : 
                sale.paymentMethod === 'Tarjeta' ? 'bg-blue-100 text-blue-700' : 'bg-purple-100 text-purple-700'
              }`}>
                {sale.paymentMethod}
              </span>
            </div>
            <div className="space-y-2 border-t border-gray-50 pt-4 mb-4">
              {sale.items.map((item, idx) => {
                const prod = products.find(p => p.id === item.productId);
                return (
                  <div key={idx} className="flex justify-between text-sm">
                    <span className="text-gray-600">{item.quantity}x {prod?.name || 'Item'}</span>
                    <span className="font-medium text-gray-900">${(item.price * item.quantity).toLocaleString()}</span>
                  </div>
                );
              })}
            </div>
            <div className="flex justify-between items-center pt-4 border-t border-gray-100">
              <span className="text-gray-500 font-medium">Total</span>
              <span className="text-xl font-bold text-orange-600">${sale.total.toLocaleString()}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Modal Nueva Venta */}
      {isAdding && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-4xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-xl font-bold flex items-center gap-2">
                <ShoppingCart className="w-6 h-6 text-orange-600" />
                Nueva Venta
              </h3>
              <button onClick={() => setIsAdding(false)}><X className="w-6 h-6 text-gray-400" /></button>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
              {/* Productos */}
              <div className="w-full md:w-2/3 p-6 overflow-y-auto bg-white border-r">
                <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
                  {products.map(p => (
                    <button
                      key={p.id}
                      onClick={() => handleAddItem(p.id)}
                      className="p-4 border rounded-xl hover:border-orange-500 hover:bg-orange-50 text-left transition-all active:scale-95"
                    >
                      <p className="font-bold text-gray-900 line-clamp-1">{p.name}</p>
                      <p className="text-sm text-orange-600 font-semibold mt-1">${p.salePrice.toLocaleString()}</p>
                      <p className="text-xs text-gray-400 mt-1">Stock: {p.stock} {p.unit}</p>
                    </button>
                  ))}
                </div>
              </div>

              {/* Resumen Carrito */}
              <div className="w-full md:w-1/3 p-6 bg-gray-50 flex flex-col">
                <h4 className="font-semibold text-gray-700 mb-4">Detalle de Orden</h4>
                <div className="flex-1 overflow-y-auto space-y-3 mb-6">
                  {currentSaleItems.length === 0 ? (
                    <p className="text-center text-gray-400 py-10 italic">Carrito vacío</p>
                  ) : (
                    currentSaleItems.map(item => {
                      const p = products.find(prod => prod.id === item.productId);
                      return (
                        <div key={item.productId} className="flex justify-between items-center bg-white p-3 rounded-lg border border-gray-100">
                          <div>
                            <p className="text-sm font-bold text-gray-800">{p?.name}</p>
                            <p className="text-xs text-gray-500">{item.quantity} x ${p?.salePrice.toLocaleString()}</p>
                          </div>
                          <div className="flex items-center gap-2">
                             <button 
                               onClick={() => setCurrentSaleItems(prev => prev.map(i => i.productId === item.productId ? {...i, quantity: Math.max(0, i.quantity - 1)} : i).filter(i => i.quantity > 0))}
                               className="w-6 h-6 rounded bg-gray-100 flex items-center justify-center hover:bg-gray-200"
                             >-</button>
                             <span className="font-bold w-4 text-center">{item.quantity}</span>
                             <button 
                               onClick={() => handleAddItem(item.productId)}
                               className="w-6 h-6 rounded bg-gray-100 flex items-center justify-center hover:bg-gray-200"
                             >+</button>
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>

                <div className="space-y-4 pt-4 border-t">
                  <input 
                    placeholder="Nombre del Cliente"
                    className="w-full px-4 py-2 bg-white border rounded-lg text-sm"
                    value={customerName}
                    onChange={e => setCustomerName(e.target.value)}
                  />
                  <div className="flex justify-between gap-2">
                    <button 
                      onClick={() => setPaymentMethod('Efectivo')}
                      className={`flex-1 py-2 rounded-lg border flex flex-col items-center gap-1 ${paymentMethod === 'Efectivo' ? 'bg-orange-50 border-orange-500 text-orange-600' : 'bg-white text-gray-500'}`}
                    >
                      <Banknote className="w-4 h-4" />
                      <span className="text-[10px]">Efectivo</span>
                    </button>
                    <button 
                      onClick={() => setPaymentMethod('Tarjeta')}
                      className={`flex-1 py-2 rounded-lg border flex flex-col items-center gap-1 ${paymentMethod === 'Tarjeta' ? 'bg-orange-50 border-orange-500 text-orange-600' : 'bg-white text-gray-500'}`}
                    >
                      <CreditCard className="w-4 h-4" />
                      <span className="text-[10px]">Tarjeta</span>
                    </button>
                    <button 
                      onClick={() => setPaymentMethod('Transferencia')}
                      className={`flex-1 py-2 rounded-lg border flex flex-col items-center gap-1 ${paymentMethod === 'Transferencia' ? 'bg-orange-50 border-orange-500 text-orange-600' : 'bg-white text-gray-500'}`}
                    >
                      <Landmark className="w-4 h-4" />
                      <span className="text-[10px]">Trf</span>
                    </button>
                  </div>
                  <div className="flex justify-between items-center text-xl font-bold text-gray-900 py-2">
                    <span>Total</span>
                    <span>${total.toLocaleString()}</span>
                  </div>
                  <button 
                    disabled={currentSaleItems.length === 0}
                    onClick={handleSubmit}
                    className="w-full py-4 bg-orange-600 text-white rounded-xl font-bold text-lg hover:bg-orange-700 disabled:opacity-50 shadow-lg shadow-orange-100"
                  >
                    Confirmar Venta
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Sales;

