    if (!acc[name]) {
      acc[name] = { name, totalSpent: 0, orderCount: 0, lastOrder: sale.date };
    }
    acc[name].totalSpent += sale.total;
    acc[name].orderCount += 1;
    if (new Date(sale.date) > new Date(acc[name].lastOrder)) {
      acc[name].lastOrder = sale.date;
    }
    return acc;
  }, {});

  const customerList = Object.values(customers).sort((a: any, b: any) => b.totalSpent - a.totalSpent);

