            <tr>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">Cliente</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">Frecuencia</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">Total Compras</th>
              <th className="px-6 py-4 text-sm font-semibold text-gray-600">Nivel</th>
