  // State initialization from local storage or defaults
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('asadopro_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('asadopro_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('asadopro_expenses');
    return saved ? JSON.parse(saved) : [];
  });

  // Persistence
  useEffect(() => {
    localStorage.setItem('asadopro_products', JSON.stringify(products));
    localStorage.setItem('asadopro_sales', JSON.stringify(sales));
    localStorage.setItem('asadopro_expenses', JSON.stringify(expenses));
  }, [products, sales, expenses]);

  // Derived Stats
  const stats = useMemo(() => {
    const totalSales = sales.reduce((acc, s) => acc + s.total, 0);
    const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
    return {
      totalSales,
      totalExpenses,
      netProfit: totalSales - totalExpenses,
      salesCount: sales.length,
      inventoryValue: products.reduce((acc, p) => acc + (p.stock * p.costPrice), 0)
    };
  }, [sales, expenses, products]);

  const handleAddSale = (sale: Omit<Sale, 'id'>) => {
    const newSale = { ...sale, id: Math.random().toString(36).substr(2, 9) };
    setSales(prev => [newSale, ...prev]);

    // Update inventory
    setProducts(prev => prev.map(p => {
      const soldItem = sale.items.find(item => item.productId === p.id);
      if (soldItem) {
        return { ...p, stock: p.stock - soldItem.quantity };
      }
      return p;
    }));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard stats={stats} recentSales={sales.slice(0, 5)} />;
      case 'inventory':
        return <Inventory products={products} setProducts={setProducts} />;
      case 'sales':
        return <Sales sales={sales} products={products} onAddSale={handleAddSale} />;
      case 'expenses':
        return <Expenses expenses={expenses} setExpenses={setExpenses} />;
      case 'customers':
        return <Customers sales={sales} />;
      case 'ai':
        return <AIInsights stats={stats} products={products} />;
      default:
        return <Dashboard stats={stats} recentSales={sales.slice(0, 5)} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

