import React, { useState, useMemo } from 'react';
import { Plus, ShoppingCart, X, CreditCard, Banknote, Landmark, Calendar, Filter, ChevronDown } from 'lucide-react';
import { Product, Sale } from '../types';

interface SalesProps {
  sales: Sale[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
}

type DateFilterType = 'today' | 'week' | 'month' | 'all' | 'custom';

const Sales: React.FC<SalesProps> = ({ sales, products, onAddSale }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [dateFilter, setDateFilter] = useState<DateFilterType>('all');
  const [customStartDate, setCustomStartDate] = useState('');
  const [customEndDate, setCustomEndDate] = useState('');

  const [currentSaleItems, setCurrentSaleItems] = useState<{productId: string, quantity: number}[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'Efectivo' | 'Transferencia' | 'Tarjeta'>('Efectivo');

  // Lógica de filtrado de ventas
  const filteredSales = useMemo(() => {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];

    return sales.filter(sale => {
      const saleDate = new Date(sale.date);
      const saleDateStr = sale.date.split('T')[0];

      switch (dateFilter) {
        case 'today':
          return saleDateStr === todayStr;
        case 'week': {
          const sevenDaysAgo = new Date();
          sevenDaysAgo.setDate(now.getDate() - 7);
          return saleDate >= sevenDaysAgo;
        }
        case 'month': {
          return saleDate.getMonth() === now.getMonth() && saleDate.getFullYear() === now.getFullYear();
        }
        case 'custom': {
          if (!customStartDate || !customEndDate) return true;
          const start = new Date(customStartDate);
          const end = new Date(customEndDate);
          end.setHours(23, 59, 59, 999); // Incluir todo el día final
          return saleDate >= start && saleDate <= end;
        }
        case 'all':
        default:
          return true;
      }
    });
  }, [sales, dateFilter, customStartDate, customEndDate]);

  const total = currentSaleItems.reduce((acc, item) => {
    const p = products.find(prod => prod.id === item.productId);
    return acc + (p ? p.salePrice * item.quantity : 0);
  }, 0);

  const handleAddItem = (productId: string) => {
    setCurrentSaleItems(prev => {
      const existing = prev.find(i => i.productId === productId);
      if (existing) {
        return prev.map(i => i.productId === productId ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { productId, quantity: 1 }];
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentSaleItems.length === 0) return;

    onAddSale({
      date: new Date().toISOString(),
      items: currentSaleItems.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        price: products.find(p => p.id === item.productId)?.salePrice || 0
      })),
      total,
      customerName,
      paymentMethod
    });

    setIsAdding(false);
    setCurrentSaleItems([]);
    setCustomerName('');
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <h3 className="text-xl font-bold text-gray-800">Historial de Ventas</h3>
          <p className="text-sm text-gray-500">Mostrando {filteredSales.length} ventas realizadas</p>
        </div>
        <button 
          onClick={() => setIsAdding(true)}
          className="bg-orange-600 text-white px-6 py-2 rounded-lg hover:bg-orange-700 flex items-center justify-center gap-2 shadow-sm font-medium transition-colors"
        >
          <Plus className="w-5 h-5" />
          Nueva Venta
        </button>
      </div>

      {/* Filtros de Fecha */}
      <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex flex-col md:flex-row gap-4 items-start md:items-center">
        <div className="flex items-center gap-2 text-gray-600">
          <Calendar className="w-5 h-5 text-orange-500" />
          <span className="text-sm font-semibold">Filtrar por:</span>
        </div>

        <div className="flex flex-wrap gap-2">
          {[
            { id: 'all', label: 'Todo' },
            { id: 'today', label: 'Hoy' },
            { id: 'week', label: '7 días' },
            { id: 'month', label: 'Este mes' },
            { id: 'custom', label: 'Personalizado' },
          ].map(filter => (
            <button
              key={filter.id}
              onClick={() => setDateFilter(filter.id as DateFilterType)}
              className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${
                dateFilter === filter.id 
                  ? 'bg-orange-600 text-white border-orange-600 shadow-sm' 
                  : 'bg-white text-gray-600 border-gray-200 hover:border-orange-300'
              }`}
            >
              {filter.label}
            </button>
          ))}
        </div>

        {dateFilter === 'custom' && (
          <div className="flex items-center gap-2 mt-2 md:mt-0 animate-in fade-in slide-in-from-left-2">
            <input 
              type="date" 
              className="text-xs border rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-orange-500 outline-none"
              value={customStartDate}
              onChange={(e) => setCustomStartDate(e.target.value)}
            />
            <span className="text-gray-400 text-xs">a</span>
            <input 
              type="date" 
              className="text-xs border rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-orange-500 outline-none"
              value={customEndDate}
              onChange={(e) => setCustomEndDate(e.target.value)}
            />
          </div>
        )}
      </div>

      {filteredSales.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredSales.map(sale => (
            <div key={sale.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <p className="text-xs text-gray-400 font-medium">{new Date(sale.date).toLocaleString('es-HN', {
                    day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit'
                  })}</p>
                  <p className="font-bold text-gray-900 mt-0.5">{sale.customerName || 'Consumidor Final'}</p>
                </div>
                <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-wider ${
                  sale.paymentMethod === 'Efectivo' ? 'bg-green-100 text-green-700' : 
                  sale.paymentMethod === 'Tarjeta' ? 'bg-blue-100 text-blue-700' : 'bg-purple-100 text-purple-700'
                }`}>
                  {sale.paymentMethod}
                </span>
              </div>
              <div className="space-y-2 border-t border-gray-50 pt-4 mb-4">
                {sale.items.map((item, idx) => {
                  const prod = products.find(p => p.id === item.productId);
                  return (
                    <div key={idx} className="flex justify-between text-sm">
                      <span className="text-gray-600">{item.quantity}x {prod?.name || 'Item'}</span>
                      <span className="font-semibold text-gray-900">L {(item.price * item.quantity).toLocaleString()}</span>
                    </div>
                  );
                })}
              </div>
              <div className="flex justify-between items-center pt-4 border-t border-gray-100">
                <span className="text-gray-500 text-xs font-bold uppercase">Total</span>
                <span className="text-lg font-black text-orange-600">L {sale.total.toLocaleString()}</span>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
          <Calendar className="w-16 h-16 text-gray-200 mb-4" />
          <p className="text-gray-500 font-medium">No se encontraron ventas en este periodo.</p>
          <button 
            onClick={() => setDateFilter('all')}
            className="mt-4 text-orange-600 font-bold hover:underline"
          >
            Ver todo el historial
          </button>
        </div>
      )}

      {/* Modal Nueva Venta */}
      {isAdding && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-4xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-xl font-bold flex items-center gap-2">
                <ShoppingCart className="w-6 h-6 text-orange-600" />
                Nueva Venta
              </h3>
              <button onClick={() => setIsAdding(false)}><X className="w-6 h-6 text-gray-400" /></button>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
              {/* Productos */}
              <div className="w-full md:w-2/3 p-6 overflow-y-auto bg-white border-r">
                <div className="grid grid-cols-2 lg:grid-cols-3 gap-3">
                  {products.map(p => (
                    <button
                      key={p.id}
                      onClick={() => handleAddItem(p.id)}
                      className="p-4 border rounded-xl hover:border-orange-500 hover:bg-orange-50 text-left transition-all active:scale-95 group"
                    >
                      <p className="font-bold text-gray-900 line-clamp-1 group-hover:text-orange-700">{p.name}</p>
                      <p className="text-sm text-orange-600 font-black mt-1">L {p.salePrice.toLocaleString()}</p>
                      <p className="text-xs text-gray-400 mt-1">Disp: {p.stock} {p.unit}</p>
                    </button>
                  ))}
                </div>
              </div>

              {/* Resumen Carrito */}
              <div className="w-full md:w-1/3 p-6 bg-gray-50 flex flex-col">
                <div className="flex items-center justify-between mb-4">
                  <h4 className="font-bold text-gray-700">Detalle de Orden</h4>
                  <span className="text-xs bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-bold">
                    {currentSaleItems.length} ítems
                  </span>
                </div>

                <div className="flex-1 overflow-y-auto space-y-3 mb-6 pr-1">
                  {currentSaleItems.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-gray-400">
                      <ShoppingCart className="w-12 h-12 opacity-10 mb-2" />
                      <p className="italic text-sm">Carrito vacío</p>
                    </div>
                  ) : (
                    currentSaleItems.map(item => {
                      const p = products.find(prod => prod.id === item.productId);
                      return (
                        <div key={item.productId} className="flex justify-between items-center bg-white p-3 rounded-lg border border-gray-100 shadow-sm animate-in zoom-in-95 duration-200">
                          <div>
                            <p className="text-sm font-bold text-gray-800">{p?.name}</p>
                            <p className="text-xs text-orange-500 font-semibold">{item.quantity} x L {p?.salePrice.toLocaleString()}</p>
                          </div>
                          <div className="flex items-center gap-2">
                             <button 
                               onClick={() => setCurrentSaleItems(prev => prev.map(i => i.productId === item.productId ? {...i, quantity: Math.max(0, i.quantity - 1)} : i).filter(i => i.quantity > 0))}
                               className="w-6 h-6 rounded bg-gray-100 flex items-center justify-center hover:bg-red-100 hover:text-red-600 transition-colors"
                             >-</button>
                             <span className="font-black w-4 text-center text-sm">{item.quantity}</span>
                             <button 
                               onClick={() => handleAddItem(item.productId)}
                               className="w-6 h-6 rounded bg-gray-100 flex items-center justify-center hover:bg-green-100 hover:text-green-600 transition-colors"
                             >+</button>
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>

                <div className="space-y-4 pt-4 border-t border-gray-200">
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Cliente</label>
                    <input 
                      placeholder="Nombre del Cliente"
                      className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none"
