                      <button 
                        onClick={() => setPaymentMethod('Transferencia')}
                        className={`flex-1 py-2 rounded-lg border flex flex-col items-center gap-1 transition-all ${paymentMethod === 'Transferencia' ? 'bg-orange-50 border-orange-500 text-orange-600 shadow-sm' : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'}`}
                      >
                        <Landmark className="w-4 h-4" />
                        <span className="text-[10px] font-bold">Trf</span>
                      </button>
                    </div>
                  </div>

                  <div className="flex justify-between items-center text-2xl font-black text-gray-900 py-2">
                    <span>Total</span>
                    <span className="text-orange-600">L {total.toLocaleString()}</span>
                  </div>

                  <button 
                    disabled={currentSaleItems.length === 0}
                    onClick={handleSubmit}
                    className="w-full py-4 bg-orange-600 text-white rounded-xl font-black text-lg hover:bg-orange-700 disabled:opacity-50 disabled:grayscale transition-all shadow-lg shadow-orange-100"
                  >
                    Confirmar Venta
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Sales;

import React, { useState, useMemo } from 'react';
import { Plus, ShoppingCart, X, CreditCard, Banknote, Landmark, Calendar, Filter, Search, Tag } from 'lucide-react';
import { Product, Sale } from '../types';

interface SalesProps {
  sales: Sale[];
  products: Product[];
  onAddSale: (sale: Omit<Sale, 'id'>) => void;
}

type DateFilterType = 'today' | 'week' | 'month' | 'all' | 'custom';

const Sales: React.FC<SalesProps> = ({ sales, products, onAddSale }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [dateFilter, setDateFilter] = useState<DateFilterType>('all');
  const [customStartDate, setCustomStartDate] = useState('');
  const [customEndDate, setCustomEndDate] = useState('');

  // Estados para la nueva venta
  const [productSearch, setProductSearch] = useState('');
  const [currentSaleItems, setCurrentSaleItems] = useState<{productId: string, quantity: number}[]>([]);
  const [customerName, setCustomerName] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<'Efectivo' | 'Transferencia' | 'Tarjeta'>('Efectivo');

  // Lógica de filtrado de ventas histórica
  const filteredSales = useMemo(() => {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];

    return sales.filter(sale => {
      const saleDate = new Date(sale.date);
      const saleDateStr = sale.date.split('T')[0];

      switch (dateFilter) {
        case 'today':
          return saleDateStr === todayStr;
        case 'week': {
          const sevenDaysAgo = new Date();
          sevenDaysAgo.setDate(now.getDate() - 7);
          return saleDate >= sevenDaysAgo;
        }
        case 'month': {
          return saleDate.getMonth() === now.getMonth() && saleDate.getFullYear() === now.getFullYear();
        }
        case 'custom': {
          if (!customStartDate || !customEndDate) return true;
          const start = new Date(customStartDate);
          const end = new Date(customEndDate);
          end.setHours(23, 59, 59, 999);
          return saleDate >= start && saleDate <= end;
        }
        case 'all':
        default:
          return true;
      }
    });
  }, [sales, dateFilter, customStartDate, customEndDate]);

  // Lógica de filtrado de productos dentro del modal
  const filteredProductsForSale = useMemo(() => {
    if (!productSearch.trim()) return products;
    const term = productSearch.toLowerCase();
    return products.filter(p => 
      p.name.toLowerCase().includes(term) || 
      p.category.toLowerCase().includes(term)
    );
  }, [products, productSearch]);

  const total = currentSaleItems.reduce((acc, item) => {
    const p = products.find(prod => prod.id === item.productId);
    return acc + (p ? p.salePrice * item.quantity : 0);
  }, 0);

  const handleAddItem = (productId: string) => {
    setCurrentSaleItems(prev => {
      const existing = prev.find(i => i.productId === productId);
      if (existing) {
        return prev.map(i => i.productId === productId ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...prev, { productId, quantity: 1 }];
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (currentSaleItems.length === 0) return;

    onAddSale({
      date: new Date().toISOString(),
      items: currentSaleItems.map(item => ({
        productId: item.productId,
        quantity: item.quantity,
        price: products.find(p => p.id === item.productId)?.salePrice || 0
      })),
      total,
      customerName,
      paymentMethod
    });

    setIsAdding(false);
    setCurrentSaleItems([]);
    setCustomerName('');
    setProductSearch('');
  };

  const handleOpenModal = () => {
    setProductSearch('');
    setIsAdding(true);
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex flex-col gap-2">
          <h3 className="text-xl font-bold text-gray-800">Historial de Ventas</h3>
          <p className="text-sm text-gray-500">Mostrando {filteredSales.length} ventas realizadas</p>
        </div>
        <button 
          onClick={handleOpenModal}
          className="bg-orange-600 text-white px-6 py-2 rounded-lg hover:bg-orange-700 flex items-center justify-center gap-2 shadow-sm font-medium transition-colors"
        >
          <Plus className="w-5 h-5" />
          Nueva Venta
        </button>
      </div>

      {/* Filtros de Fecha */}
      <div className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm flex flex-col md:flex-row gap-4 items-start md:items-center">
        <div className="flex items-center gap-2 text-gray-600">
          <Calendar className="w-5 h-5 text-orange-500" />
          <span className="text-sm font-semibold">Filtrar por:</span>
        </div>

        <div className="flex flex-wrap gap-2">
          {[
            { id: 'all', label: 'Todo' },
            { id: 'today', label: 'Hoy' },
            { id: 'week', label: '7 días' },
            { id: 'month', label: 'Este mes' },
            { id: 'custom', label: 'Personalizado' },
          ].map(filter => (
            <button
              key={filter.id}
              onClick={() => setDateFilter(filter.id as DateFilterType)}
              className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${
                dateFilter === filter.id 
                  ? 'bg-orange-600 text-white border-orange-600 shadow-sm' 
                  : 'bg-white text-gray-600 border-gray-200 hover:border-orange-300'
              }`}
            >
              {filter.label}
            </button>
          ))}
        </div>

        {dateFilter === 'custom' && (
          <div className="flex items-center gap-2 mt-2 md:mt-0 animate-in fade-in slide-in-from-left-2">
            <input 
              type="date" 
              className="text-xs border rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-orange-500 outline-none"
              value={customStartDate}
              onChange={(e) => setCustomStartDate(e.target.value)}
            />
            <span className="text-gray-400 text-xs">a</span>
            <input 
              type="date" 
              className="text-xs border rounded-lg px-2 py-1.5 focus:ring-2 focus:ring-orange-500 outline-none"
              value={customEndDate}
              onChange={(e) => setCustomEndDate(e.target.value)}
            />
          </div>
        )}
      </div>

      {filteredSales.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredSales.map(sale => (
            <div key={sale.id} className="bg-white p-5 rounded-xl border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <p className="text-xs text-gray-400 font-medium">{new Date(sale.date).toLocaleString('es-HN', {
                    day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit'
                  })}</p>
                  <p className="font-bold text-gray-900 mt-0.5">{sale.customerName || 'Consumidor Final'}</p>
                </div>
                <span className={`text-[10px] px-2 py-1 rounded-full font-bold uppercase tracking-wider ${
                  sale.paymentMethod === 'Efectivo' ? 'bg-green-100 text-green-700' : 
                  sale.paymentMethod === 'Tarjeta' ? 'bg-blue-100 text-blue-700' : 'bg-purple-100 text-purple-700'
                }`}>
                  {sale.paymentMethod}
                </span>
              </div>
              <div className="space-y-2 border-t border-gray-50 pt-4 mb-4">
                {sale.items.map((item, idx) => {
                  const prod = products.find(p => p.id === item.productId);
                  return (
                    <div key={idx} className="flex justify-between text-sm">
                      <span className="text-gray-600">{item.quantity}x {prod?.name || 'Item'}</span>
                      <span className="font-semibold text-gray-900">L {(item.price * item.quantity).toLocaleString()}</span>
                    </div>
                  );
                })}
              </div>
              <div className="flex justify-between items-center pt-4 border-t border-gray-100">
                <span className="text-gray-500 text-xs font-bold uppercase">Total</span>
                <span className="text-lg font-black text-orange-600">L {sale.total.toLocaleString()}</span>
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="flex flex-col items-center justify-center py-20 bg-white rounded-2xl border border-dashed border-gray-300">
          <Calendar className="w-16 h-16 text-gray-200 mb-4" />
          <p className="text-gray-500 font-medium">No se encontraron ventas en este periodo.</p>
          <button 
            onClick={() => setDateFilter('all')}
            className="mt-4 text-orange-600 font-bold hover:underline"
          >
            Ver todo el historial
          </button>
        </div>
      )}

      {/* Modal Nueva Venta */}
      {isAdding && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black bg-opacity-50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl w-full max-w-5xl max-h-[90vh] flex flex-col shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
            <div className="p-6 border-b flex justify-between items-center bg-gray-50">
              <h3 className="text-xl font-bold flex items-center gap-2">
                <ShoppingCart className="w-6 h-6 text-orange-600" />
                Nueva Venta
              </h3>
              <button onClick={() => setIsAdding(false)} className="hover:bg-gray-200 p-1 rounded-full transition-colors">
                <X className="w-6 h-6 text-gray-400" />
              </button>
            </div>

            <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
              {/* Selección de Productos */}
              <div className="w-full md:w-2/3 p-6 overflow-y-auto bg-white border-r flex flex-col gap-6">
                {/* Buscador de productos */}
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                  <input 
                    type="text"
                    placeholder="Buscar por nombre o categoría (ej: carnes, tajo)..."
                    className="w-full pl-10 pr-10 py-3 bg-gray-50 border border-gray-200 rounded-xl focus:ring-2 focus:ring-orange-500 outline-none transition-all font-medium text-sm"
                    value={productSearch}
                    onChange={(e) => setProductSearch(e.target.value)}
                    autoFocus
                  />
                  {productSearch && (
                    <button 
                      onClick={() => setProductSearch('')}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  )}
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  {filteredProductsForSale.length > 0 ? (
                    filteredProductsForSale.map(p => (
                      <button
                        key={p.id}
                        onClick={() => handleAddItem(p.id)}
                        className="p-4 border border-gray-100 rounded-xl hover:border-orange-500 hover:bg-orange-50 text-left transition-all active:scale-95 group relative overflow-hidden shadow-sm"
                      >
                        <div className="flex justify-between items-start mb-2">
                          <span className="text-[10px] font-black text-gray-400 uppercase tracking-tighter bg-gray-100 px-1.5 py-0.5 rounded">
                            {p.category}
                          </span>
                        </div>
                        <p className="font-bold text-gray-900 line-clamp-1 group-hover:text-orange-700">{p.name}</p>
                        <div className="flex justify-between items-end mt-3">
                          <p className="text-sm text-orange-600 font-black">L {p.salePrice.toLocaleString()}</p>
                          <p className={`text-[10px] font-bold ${p.stock <= 5 ? 'text-red-500' : 'text-gray-400'}`}>
                            Stock: {p.stock}
                          </p>
                        </div>
                        <div className="absolute top-0 right-0 p-1 opacity-0 group-hover:opacity-100 transition-opacity">
                          <Plus className="w-4 h-4 text-orange-500" />
                        </div>
                      </button>
                    ))
                  ) : (
                    <div className="col-span-full py-12 text-center flex flex-col items-center">
                      <Tag className="w-12 h-12 text-gray-200 mb-2" />
                      <p className="text-gray-400 font-medium italic">No se encontraron productos para "{productSearch}"</p>
                    </div>
                  )}
                </div>
              </div>

              {/* Resumen Carrito y Pago */}
              <div className="w-full md:w-1/3 p-6 bg-gray-50 flex flex-col border-t md:border-t-0">
                <div className="flex items-center justify-between mb-4">
                  <h4 className="font-bold text-gray-700">Detalle de Orden</h4>
                  <span className="text-xs bg-orange-100 text-orange-600 px-2 py-0.5 rounded-full font-bold">
                    {currentSaleItems.length} ítems
                  </span>
                </div>

                <div className="flex-1 overflow-y-auto space-y-3 mb-6 pr-1 custom-scrollbar">
                  {currentSaleItems.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full text-gray-400">
                      <ShoppingCart className="w-12 h-12 opacity-10 mb-2" />
                      <p className="italic text-sm">Carrito vacío</p>
                    </div>
                  ) : (
                    currentSaleItems.map(item => {
                      const p = products.find(prod => prod.id === item.productId);
                      return (
                        <div key={item.productId} className="flex justify-between items-center bg-white p-3 rounded-lg border border-gray-100 shadow-sm animate-in zoom-in-95 duration-200">
                          <div className="flex-1">
                            <p className="text-sm font-bold text-gray-800 line-clamp-1">{p?.name}</p>
                            <p className="text-xs text-orange-500 font-semibold">{item.quantity} x L {p?.salePrice.toLocaleString()}</p>
                          </div>
                          <div className="flex items-center gap-2 ml-3">
                             <button 
                               onClick={() => setCurrentSaleItems(prev => prev.map(i => i.productId === item.productId ? {...i, quantity: Math.max(0, i.quantity - 1)} : i).filter(i => i.quantity > 0))}
                               className="w-7 h-7 rounded-lg bg-gray-100 flex items-center justify-center hover:bg-red-100 hover:text-red-600 transition-colors"
                             >-</button>
                             <span className="font-black w-4 text-center text-sm">{item.quantity}</span>
                             <button 
                               onClick={() => handleAddItem(item.productId)}
                               className="w-7 h-7 rounded-lg bg-gray-100 flex items-center justify-center hover:bg-green-100 hover:text-green-600 transition-colors"
                             >+</button>
                          </div>
                        </div>
                      );
                    })
                  )}
                </div>

                <div className="space-y-4 pt-4 border-t border-gray-200 mt-auto">
                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Cliente</label>
                    <input 
                      placeholder="Nombre del Cliente"
                      className="w-full px-4 py-2 bg-white border border-gray-200 rounded-lg text-sm focus:ring-2 focus:ring-orange-500 outline-none"
                      value={customerName}
                      onChange={e => setCustomerName(e.target.value)}
                    />
                  </div>

                  <div>
                    <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1 block">Método de Pago</label>
                    <div className="flex justify-between gap-2">
                      <button 
                        onClick={() => setPaymentMethod('Efectivo')}
                        className={`flex-1 py-2 rounded-lg border flex flex-col items-center gap-1 transition-all ${paymentMethod === 'Efectivo' ? 'bg-orange-50 border-orange-500 text-orange-600 shadow-sm' : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'}`}
                      >
                        <Banknote className="w-4 h-4" />
                        <span className="text-[10px] font-bold">Efectivo</span>
                      </button>
                      <button 
                        onClick={() => setPaymentMethod('Tarjeta')}
                        className={`flex-1 py-2 rounded-lg border flex flex-col items-center gap-1 transition-all ${paymentMethod === 'Tarjeta' ? 'bg-orange-50 border-orange-500 text-orange-600 shadow-sm' : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'}`}
                      >
                        <CreditCard className="w-4 h-4" />
                        <span className="text-[10px] font-bold">Tarjeta</span>
                      </button>
                      <button 
                        onClick={() => setPaymentMethod('Transferencia')}
                        className={`flex-1 py-2 rounded-lg border flex flex-col items-center gap-1 transition-all ${paymentMethod === 'Transferencia' ? 'bg-orange-50 border-orange-500 text-orange-600 shadow-sm' : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'}`}
                      >
                        <Landmark className="w-4 h-4" />
                        <span className="text-[10px] font-bold">Trf</span>
                      </button>
                    </div>
                  </div>

                  <div className="flex justify-between items-center text-2xl font-black text-gray-900 py-2">
                    <span>Total</span>
                    <span className="text-orange-600">L {total.toLocaleString()}</span>
                  </div>

                  <button 
                    disabled={currentSaleItems.length === 0}
                    onClick={handleSubmit}
                    className="w-full py-4 bg-orange-600 text-white rounded-xl font-black text-lg hover:bg-orange-700 disabled:opacity-50 disabled:grayscale transition-all shadow-lg shadow-orange-100 active:scale-[0.98]"
                  >
                    Confirmar Venta
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Sales;

import React, { useState, useMemo } from 'react';
import { Users, Phone, Star, ShoppingBag, Search, X } from 'lucide-react';
import { Sale } from '../types';

interface CustomersProps {
  sales: Sale[];
}

const Customers: React.FC<CustomersProps> = ({ sales }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Aggregate and filter customers from sales
  const customerList = useMemo(() => {
    const customersMap = sales.reduce((acc: any, sale) => {
      const name = sale.customerName || 'Consumidor Final';
      if (!acc[name]) {
        acc[name] = { name, totalSpent: 0, orderCount: 0, lastOrder: sale.date };
      }
      acc[name].totalSpent += sale.total;
      acc[name].orderCount += 1;
      if (new Date(sale.date) > new Date(acc[name].lastOrder)) {
        acc[name].lastOrder = sale.date;
      }
      return acc;
    }, {});

    const list = Object.values(customersMap) as any[];

    // Filter by search term
    const filtered = list.filter((c: any) => 
      c.name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Sort by total spent descending
    return filtered.sort((a: any, b: any) => b.totalSpent - a.totalSpent);
  }, [sales, searchTerm]);

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 flex-1">
          <div className="bg-white p-6 rounded-xl border shadow-sm flex items-center gap-4">
            <div className="p-3 bg-purple-100 rounded-lg text-purple-600">
              <Users className="w-6 h-6" />
            </div>
            <div>
              <p className="text-xs text-gray-500 font-bold uppercase">Clientes Únicos</p>
              <p className="text-2xl font-black text-gray-900">{customerList.length}</p>
            </div>
          </div>
        </div>

        <div className="relative w-full md:w-80">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
          <input 
            type="text" 
            placeholder="Buscar cliente por nombre..." 
            className="w-full pl-10 pr-10 py-2.5 bg-white border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500 transition-all shadow-sm text-sm"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
          {searchTerm && (
            <button 
              onClick={() => setSearchTerm('')}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
            >
              <X className="w-4 h-4" />
            </button>
          )}
        </div>
      </div>

      <div className="bg-white rounded-xl border border-gray-200 overflow-hidden shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-gray-50 border-b">
              <tr>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600 uppercase tracking-wider">Cliente</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600 uppercase tracking-wider">Frecuencia</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600 uppercase tracking-wider">Total Compras</th>
                <th className="px-6 py-4 text-sm font-semibold text-gray-600 uppercase tracking-wider">Nivel</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {customerList.length > 0 ? (
                customerList.map((customer: any, idx) => (
                  <tr key={idx} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 rounded-full bg-orange-100 flex items-center justify-center text-orange-600 font-bold border border-orange-200">
                          {customer.name.charAt(0)}
                        </div>
                        <div>
                          <p className="font-bold text-gray-900">{customer.name}</p>
                          <p className="text-xs text-gray-400 font-medium">Última: {new Date(customer.lastOrder).toLocaleDateString()}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-2">
                        <ShoppingBag className="w-4 h-4 text-gray-400" />
                        <span className="font-medium text-gray-700">{customer.orderCount} pedidos</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 font-black text-gray-900">
                      L {customer.totalSpent.toLocaleString()}
                    </td>
                    <td className="px-6 py-4">
                      {customer.orderCount > 3 ? (
                        <span className="inline-flex items-center gap-1 bg-yellow-100 text-yellow-700 px-2.5 py-1 rounded-full text-xs font-black border border-yellow-200 shadow-sm">
                          <Star className="w-3 h-3 fill-yellow-700" /> VIP
                        </span>
                      ) : (
                        <span className="text-gray-400 text-xs font-bold uppercase tracking-widest bg-gray-50 px-2.5 py-1 rounded-full border border-gray-100">
                          Regular
                        </span>
                      )}
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={4} className="py-20 text-center">
                    <div className="flex flex-col items-center justify-center">
                      {searchTerm ? (
                        <>
                          <Search className="w-12 h-12 text-gray-200 mb-4" />
                          <p className="text-gray-400 font-medium italic">No se encontraron clientes para "{searchTerm}"</p>
                        </>
                      ) : (
                        <>
                          <Users className="w-12 h-12 text-gray-200 mb-4" />
                          <p className="text-gray-400 font-medium">Registra ventas para ver tus clientes aquí.</p>
                        </>
                      )}
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Customers;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import Inventory from './views/Inventory';
import Sales from './views/Sales';
import Expenses from './views/Expenses';
import AIInsights from './views/AIInsights';
import Customers from './views/Customers';
import { Product, Sale, Expense, ProductCategory } from './types';

const INITIAL_PRODUCTS: Product[] = [
  { id: '1', name: 'Tajo de Res', category: ProductCategory.MEAT, costPrice: 90, salePrice: 130, stock: 15, unit: 'kg' },
  { id: '2', name: 'Churrasco Especial', category: ProductCategory.MEAT, costPrice: 110, salePrice: 175, stock: 8, unit: 'kg' },
  { id: '3', name: 'Orden de Tajadas', category: ProductCategory.SIDES, costPrice: 15, salePrice: 45, stock: 60, unit: 'porcion' },
  { id: '4', name: 'Refresco 500ml', category: ProductCategory.DRINKS, costPrice: 14, salePrice: 22, stock: 48, unit: 'unidad' },
];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');

  // State initialization from local storage or defaults
  const [products, setProducts] = useState<Product[]>(() => {
    const saved = localStorage.getItem('asadopro_products');
    return saved ? JSON.parse(saved) : INITIAL_PRODUCTS;
  });

  const [sales, setSales] = useState<Sale[]>(() => {
    const saved = localStorage.getItem('asadopro_sales');
    return saved ? JSON.parse(saved) : [];
  });

  const [expenses, setExpenses] = useState<Expense[]>(() => {
    const saved = localStorage.getItem('asadopro_expenses');
    return saved ? JSON.parse(saved) : [];
  });

  const [weeklyGoal, setWeeklyGoal] = useState<number>(() => {
    const saved = localStorage.getItem('asadopro_weekly_goal');
    return saved ? JSON.parse(saved) : 5000; // Default goal
  });

  // Persistence
  useEffect(() => {
    localStorage.setItem('asadopro_products', JSON.stringify(products));
    localStorage.setItem('asadopro_sales', JSON.stringify(sales));
    localStorage.setItem('asadopro_expenses', JSON.stringify(expenses));
    localStorage.setItem('asadopro_weekly_goal', JSON.stringify(weeklyGoal));
  }, [products, sales, expenses, weeklyGoal]);

  // Derived Stats
  const stats = useMemo(() => {
    const totalSales = sales.reduce((acc, s) => acc + s.total, 0);
    const totalExpenses = expenses.reduce((acc, e) => acc + e.amount, 0);
    return {
      totalSales,
      totalExpenses,
      netProfit: totalSales - totalExpenses,
      salesCount: sales.length,
      inventoryValue: products.reduce((acc, p) => acc + (p.stock * p.costPrice), 0)
    };
  }, [sales, expenses, products]);

  const handleAddSale = (sale: Omit<Sale, 'id'>) => {
    const newSale = { ...sale, id: Math.random().toString(36).substr(2, 9) };
    setSales(prev => [newSale, ...prev]);

    // Update inventory
    setProducts(prev => prev.map(p => {
      const soldItem = sale.items.find(item => item.productId === p.id);
      if (soldItem) {
        return { ...p, stock: p.stock - soldItem.quantity };
      }
      return p;
    }));
  };

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard stats={stats} sales={sales} expenses={expenses} weeklyGoal={weeklyGoal} setWeeklyGoal={setWeeklyGoal} />;
      case 'inventory':
        return <Inventory products={products} setProducts={setProducts} />;
      case 'sales':
        return <Sales sales={sales} products={products} onAddSale={handleAddSale} />;
      case 'expenses':
        return <Expenses expenses={expenses} setExpenses={setExpenses} />;
      case 'customers':
        return <Customers sales={sales} />;
      case 'ai':
        return <AIInsights stats={stats} products={products} />;
      default:
        return <Dashboard stats={stats} sales={sales} expenses={expenses} weeklyGoal={weeklyGoal} setWeeklyGoal={setWeeklyGoal} />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { 
